#include <iostream>
#include <string>
using namespace std;

bool isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

int main() {
    string s;
    while (cin >> s) {
        bool valid = true;

        for (size_t i = 0; i < s.size(); ++i) {
            if (!isVowel(s[i]) && s[i] != 'n') {
                if (i + 1 >= s.size() || !isVowel(s[i + 1])) {
                    valid = false;
                    break;
                }
                ++i;
            }
        }

        cout << (valid ? "YES" : "NO") << '\n';
    }

    return 0;
}

